CREATE DATABASE IF NOT EXISTS campushire; USE campushire; SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS notification,placement,round_result,recruitment_round,application,drive_skill,drive_department,eligibility_rule,placement_drive,job_role,company,resume,certification,project_member,project,student_skill,skill,school_academic_record,academic_record,student,users,department; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE department(department_id INT AUTO_INCREMENT PRIMARY KEY,department_name VARCHAR(100) UNIQUE NOT NULL,department_code VARCHAR(20) UNIQUE NOT NULL);
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('STUDENT','FACULTY','COMPANY') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student(student_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,department_id INT NOT NULL,roll_number VARCHAR(30) UNIQUE,first_name VARCHAR(80),last_name VARCHAR(80),phone VARCHAR(20),graduation_year INT,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES department(department_id));
CREATE TABLE academic_record(academic_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,semester INT NOT NULL,cgpa DECIMAL(4,2),backlogs INT DEFAULT 0,UNIQUE(student_id,semester),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE);
CREATE TABLE school_academic_record(school_record_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT UNIQUE NOT NULL,tenth_percentage DECIMAL(5,2),twelfth_percentage DECIMAL(5,2),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE);
CREATE TABLE skill(skill_id INT AUTO_INCREMENT PRIMARY KEY,skill_name VARCHAR(80) UNIQUE NOT NULL,category VARCHAR(80));
CREATE TABLE student_skill(student_id INT,skill_id INT,proficiency_level VARCHAR(30),verified BOOLEAN DEFAULT 0,PRIMARY KEY(student_id,skill_id),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skill(skill_id) ON DELETE CASCADE);
CREATE TABLE project(project_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description TEXT,project_url VARCHAR(255));
CREATE TABLE project_member(project_id INT,student_id INT,role VARCHAR(80),PRIMARY KEY(project_id,student_id),FOREIGN KEY(project_id) REFERENCES project(project_id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE);
CREATE TABLE certification(certification_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,name VARCHAR(150),issuing_organization VARCHAR(150),issue_date DATE,credential_url VARCHAR(255),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE);
CREATE TABLE resume(resume_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,file_path VARCHAR(255),version INT DEFAULT 1,is_current BOOLEAN DEFAULT 1,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE);
CREATE TABLE company(company_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE,company_name VARCHAR(150) NOT NULL,industry VARCHAR(100),website VARCHAR(255),location VARCHAR(120),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE job_role(job_role_id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,role_name VARCHAR(150) NOT NULL,job_description TEXT,FOREIGN KEY(company_id) REFERENCES company(company_id) ON DELETE CASCADE);
CREATE TABLE placement_drive(drive_id INT AUTO_INCREMENT PRIMARY KEY,job_role_id INT NOT NULL,drive_name VARCHAR(150),package_lpa DECIMAL(7,2),location VARCHAR(120),drive_date DATE,application_deadline DATE,status ENUM('OPEN','CLOSED','UPCOMING') DEFAULT 'OPEN',description TEXT,FOREIGN KEY(job_role_id) REFERENCES job_role(job_role_id) ON DELETE CASCADE);
CREATE TABLE eligibility_rule(rule_id INT AUTO_INCREMENT PRIMARY KEY,drive_id INT UNIQUE NOT NULL,min_cgpa DECIMAL(4,2) DEFAULT 0,max_backlogs INT DEFAULT 0,min_tenth_percentage DECIMAL(5,2) DEFAULT 0,min_twelfth_percentage DECIMAL(5,2) DEFAULT 0,graduation_year INT,FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE);
CREATE TABLE drive_department(drive_id INT,department_id INT,PRIMARY KEY(drive_id,department_id),FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES department(department_id) ON DELETE CASCADE);
CREATE TABLE drive_skill(drive_id INT,skill_id INT,is_mandatory BOOLEAN DEFAULT 1,PRIMARY KEY(drive_id,skill_id),FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skill(skill_id) ON DELETE CASCADE);
CREATE TABLE application(application_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,drive_id INT,status ENUM('APPLIED','APTITUDE','TECHNICAL','HR','SELECTED','REJECTED') DEFAULT 'APPLIED',rejection_reason TEXT,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(student_id,drive_id),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE,FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE);
CREATE TABLE recruitment_round(round_id INT AUTO_INCREMENT PRIMARY KEY,drive_id INT,round_name VARCHAR(80),round_number INT,UNIQUE(drive_id,round_number),FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE);
CREATE TABLE round_result(result_id INT AUTO_INCREMENT PRIMARY KEY,round_id INT,application_id INT,result ENUM('PASSED','FAILED','PENDING') DEFAULT 'PENDING',remarks VARCHAR(255),UNIQUE(round_id,application_id),FOREIGN KEY(round_id) REFERENCES recruitment_round(round_id) ON DELETE CASCADE,FOREIGN KEY(application_id) REFERENCES application(application_id) ON DELETE CASCADE);
CREATE TABLE placement(placement_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT UNIQUE,drive_id INT,placed_at DATE DEFAULT(CURRENT_DATE),FOREIGN KEY(student_id) REFERENCES student(student_id) ON DELETE CASCADE,FOREIGN KEY(drive_id) REFERENCES placement_drive(drive_id) ON DELETE CASCADE);
CREATE TABLE notification(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(150),message TEXT,is_read BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
